<script setup>
import { computed, ref, watch } from 'vue'
import { copyFor } from './copy.js'
import { parseThresholdInput } from './threshold.js'
import { outgoing, nodeById, insertOnEdge, deleteUnit, moveUnit, addBranch, deleteBranch, moveBranch } from './model.js'
const props = defineProps({definition:Object, selection:Object, locale:String, people:Array, busy:Boolean, editable:Boolean})
const emit = defineEmits(['change','error','select'])
const t=computed(()=>copyFor(props.locale)), target=ref('')
const node=computed(()=>props.selection?.kind==='node'?nodeById(props.definition,props.selection.id):null)
const edge=computed(()=>props.selection?.kind==='edge'?props.definition?.edges.find(e=>e.id===props.selection.id):null)
const split=computed(()=>edge.value?nodeById(props.definition,edge.value.source):null)
const isBranch=computed(()=>['exclusiveGateway','parallelFork'].includes(split.value?.type))
const human=computed(()=>['approval','parallelApproval'].includes(node.value?.type))
const region=computed(()=>['exclusiveGateway','parallelFork'].includes(node.value?.type))
const movable=computed(()=>human.value||region.value)
const branches=computed(()=>region.value?outgoing(props.definition,node.value.id):[])
const branchIndex=computed(()=>edge.value?outgoing(props.definition,edge.value.source).findIndex(e=>e.id===edge.value.id):-1)
watch(()=>props.selection,()=>target.value='')
function operation(fn) { try { emit('change',fn()) } catch(error) { emit('error',error) } }
function updateNode(key,value) { emit('change',{...props.definition,nodes:props.definition.nodes.map(n=>n.id===node.value.id?{...n,[key]:value}:n)}) }
function changeHuman(type) { const ids=node.value.assigneeIds; emit('change',{...props.definition,nodes:props.definition.nodes.map(n=>n.id===node.value.id?{...n,type,assigneeIds:type==='approval'?ids.slice(0,1):ids,completionMode:type==='approval'?'ALL':n.completionMode}:n)}) }
function participant(id,checked) { updateNode('assigneeIds',node.value.type==='approval'?[id]:checked?[...new Set([...node.value.assigneeIds,id])]:node.value.assigneeIds.filter(value=>value!==id)) }
function updateEdge(changes) { emit('change',{...props.definition,edges:props.definition.edges.map(e=>e.id===edge.value.id?{...e,...changes}:e)}) }
function predicate(index,key,value) { updateEdge({condition:{...edge.value.condition,predicates:edge.value.condition.predicates.map((p,i)=>i===index?{...p,[key]:value}:p)}}) }
function threshold(index,text) { const parsed=parseThresholdInput(text,edge.value.condition.predicates[index].currency);predicate(index,'threshold',parsed===null?text:parsed) }
function currency(index,value) {const rule=edge.value.condition.predicates[index],text=String(rule.threshold??''),parsed=parseThresholdInput(text,value);updateEdge({condition:{...edge.value.condition,predicates:edge.value.condition.predicates.map((p,i)=>i===index?{...p,currency:value,threshold:parsed===null?text:parsed}:p)}})}
function addPredicate() { updateEdge({condition:{...edge.value.condition,predicates:[...edge.value.condition.predicates,{field:'payment.netTotal',operator:'GTE',currency:edge.value.condition.predicates[0]?.currency||'CNY',threshold:0}]}}) }
const labelEdge=e=>`${nodeById(props.definition,e.source)?.name || e.source} → ${nodeById(props.definition,e.target)?.name || e.target}${e.label?` · ${e.label}`:''}`
</script>
<template>
  <aside class="gf-inspector" tabindex="-1" :aria-label="t.properties" data-testid="graph-properties" :data-selected-kind="selection?.kind" :data-selected-id="selection?.id" :data-default-branch="edge?String(edge.defaultBranch):undefined"><header><span class="gf-eyebrow">{{ t.properties }}</span><h2>{{ node?.name || edge?.label || t.edge }}</h2></header>
    <p v-if="!selection" class="gf-muted">{{ t.choose }}</p>
    <template v-else-if="node"><label>{{ t.nodeName }}<input :value="node.name" :disabled="busy || !editable" maxlength="120" data-testid="graph-node-name" @input="updateNode('name',$event.target.value)"></label><p class="gf-muted">{{ t[node.type] }} <span class="gf-id">{{ node.id }}</span></p>
      <template v-if="human"><label>{{ t.type }}<select :value="node.type" :disabled="busy || !editable" data-testid="graph-node-type" @change="changeHuman($event.target.value)"><option value="approval">{{ t.approval }}</option><option value="parallelApproval">{{ t.parallelApproval }}</option></select></label><fieldset class="gf-participants"><legend>{{ t.participants }}</legend><label v-for="person in people" :key="person.id"><input :type="node.type==='approval'?'radio':'checkbox'" name="graph-assignee" :value="person.id" :checked="node.assigneeIds.includes(person.id)" :disabled="busy || !editable" :data-testid="`graph-person-${person.id}`" @change="participant(person.id,$event.target.checked)">{{ person.displayName }}<small>{{ person.id }}</small></label><p v-if="!people.length">{{ t.noPeople }}</p></fieldset><label v-if="node.type==='parallelApproval'">{{ t.groupRule }}<select :value="node.completionMode" :disabled="busy || !editable" data-testid="graph-vote-mode" @change="updateNode('completionMode',$event.target.value)"><option value="ALL">ALL</option><option value="ANY">ANY</option></select></label><p class="gf-callout">{{ node.completionMode==='ANY'?t.anyHelp:t.allHelp }}</p></template>
      <template v-if="node.pairId"><p class="gf-muted">{{ t.paired }}: {{ nodeById(definition,node.pairId)?.name }}</p><p class="gf-callout">{{ ['parallelFork','parallelJoin'].includes(node.type)?t.pathHelp:t.conditionHelp }}</p></template>
      <template v-if="region"><h3>{{ t.branchOrder }}</h3><ol class="gf-branch-list"><li v-for="(branch,i) in branches" :key="branch.id"><button type="button" class="gf-text-button" @click="emit('select',{kind:'edge',id:branch.id})">{{ i+1 }}. {{ branch.label || t.branch }} {{ branch.defaultBranch?'· '+t.default:'' }}</button></li></ol><button type="button" class="secondary" data-testid="graph-add-branch" :disabled="busy || !editable || branches.length>=4" @click="operation(()=>addBranch(definition,node.id,people,locale))">＋ {{ t.addBranch }}</button></template>
      <template v-if="movable && editable"><hr><label>{{ t.destination }}<select v-model="target" data-testid="graph-move-target" :disabled="busy"><option value="">{{ t.move }}</option><option v-for="item in definition.edges" :key="item.id" :value="item.id">{{ labelEdge(item) }}</option></select></label><button type="button" class="secondary" :disabled="busy || !target" data-testid="graph-move" @click="operation(()=>moveUnit(definition,node.id,target))">{{ t.moveHere }}</button><p class="gf-muted">{{ t.deleteHelp }}</p><button type="button" class="gf-danger" :disabled="busy" data-testid="graph-delete" @click="operation(()=>deleteUnit(definition,node.id))">{{ t.delete }}</button></template>
    </template>
    <template v-else-if="edge"><p class="gf-muted gf-wrap">{{ labelEdge(edge) }}</p><template v-if="isBranch"><p class="gf-callout">{{ split.type==='exclusiveGateway'?t.conditionHelp:t.pathHelp }}</p><label>{{ t.branchName }}<input :value="edge.label" :disabled="busy || !editable" maxlength="120" data-testid="graph-branch-name" @input="updateEdge({label:$event.target.value})"></label><p v-if="edge.defaultBranch" class="gf-callout">{{ t.defaultHelp }}</p><template v-if="edge.condition"><label>{{ t.predicateMode }}<select :value="edge.condition.mode" :disabled="busy || !editable" data-testid="graph-condition-mode" @change="updateEdge({condition:{...edge.condition,mode:$event.target.value}})"><option value="ALL">{{ t.predicateAll }}</option><option value="ANY">{{ t.predicateAny }}</option></select></label><fieldset v-for="(rule,i) in edge.condition.predicates" :key="i" class="gf-predicate" :data-field="rule.field"><legend>{{ t.field }} {{ i+1 }}</legend><label>{{ t.operator }}<select :value="rule.operator" :disabled="busy || !editable" :data-testid="`graph-operator-${i}`" @change="predicate(i,'operator',$event.target.value)"><option v-for="op in ['EQ','GT','GTE','LT','LTE']" :key="op" :value="op">{{ {EQ:'=',GT:'>',GTE:'≥',LT:'<',LTE:'≤'}[op] }}</option></select></label><label>{{ t.threshold }}<input type="text" inputmode="decimal" maxlength="32" :aria-invalid="typeof rule.threshold!=='number'" :value="rule.threshold" :disabled="busy || !editable" :data-testid="`graph-threshold-${i}`" @input="threshold(i,$event.target.value)"><span v-if="typeof rule.threshold!=='number'" class="gf-field-error" :data-testid="`graph-threshold-error-${i}`">{{ locale==='zh'?'请输入 0–20,000,000,000 的金额，最多两位小数；日元须为整数。':'Enter 0–20,000,000,000 with up to two decimal places; JPY must be whole yen.' }}</span></label><label>{{ t.currency }}<select :value="rule.currency" :disabled="busy || !editable" :data-testid="`graph-condition-currency-${i}`" @change="currency(i,$event.target.value)"><option v-for="c in ['CNY','USD','EUR','GBP','JPY']" :key="c">{{ c }}</option></select></label><button type="button" class="gf-text-button" :disabled="busy || !editable || edge.condition.predicates.length<=1" @click="updateEdge({condition:{...edge.condition,predicates:edge.condition.predicates.filter((_,j)=>j!==i)}})">{{ t.removePredicate }}</button></fieldset><button type="button" class="secondary" :disabled="busy || !editable || edge.condition.predicates.length>=8" @click="addPredicate">＋ {{ t.addPredicate }}</button></template><div class="gf-button-row"><button type="button" :disabled="busy || !editable || edge.defaultBranch || branchIndex===0" @click="operation(()=>moveBranch(definition,edge.id,-1))">↑ {{ t.up }}</button><button type="button" :disabled="busy || !editable || edge.defaultBranch || branchIndex >= outgoing(definition,edge.source).length-(split.type==='exclusiveGateway'?2:1)" @click="operation(()=>moveBranch(definition,edge.id,1))">↓ {{ t.down }}</button></div><button type="button" class="gf-danger" :disabled="busy || !editable || edge.defaultBranch || outgoing(definition,edge.source).length<=2" @click="operation(()=>deleteBranch(definition,edge.id))">{{ t.removeBranch }}</button></template>
      <template v-if="editable"><hr><h3>{{ t.insert }}</h3><div class="gf-insert-options"><button v-for="type in ['approval','parallelApproval','exclusiveGateway','parallelFork']" :key="type" type="button" class="secondary" :data-testid="`graph-insert-${type}`" :disabled="busy" @click="operation(()=>insertOnEdge(definition,edge.id,type,people,locale))">＋ {{ t[type] }}</button></div></template>
    </template>
  </aside>
</template>
